// Description: C header of the dma_engine register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-12
#ifndef DMA_ENGINE_REGS_H
#define DMA_ENGINE_REGS_H
#define DMA_ENGINE_REGS_ID_OFFSET 0x00u
#define DMA_ENGINE_REGS_VERSION_OFFSET 0x04u
#define DMA_ENGINE_REGS_DATE_OFFSET 0x08u
#define DMA_ENGINE_REGS_ID_VALUE 0x444D4145u   /* "DMAE" */
#define DMA_ENGINE_REGS_CTRL_OFFSET 0x10u   /* RW */
#define DMA_ENGINE_REGS_CTRL_RESET 0x00000000u
#define DMA_ENGINE_REGS_CTRL_START_SHIFT 0u
#define DMA_ENGINE_REGS_CTRL_START_MASK 0x00000001u
#define DMA_ENGINE_REGS_CTRL_IRQ_EN_SHIFT 1u
#define DMA_ENGINE_REGS_CTRL_IRQ_EN_MASK 0x00000002u
#define DMA_ENGINE_REGS_SRC_OFFSET 0x14u   /* RW */
#define DMA_ENGINE_REGS_SRC_RESET 0x00000000u
#define DMA_ENGINE_REGS_DST_OFFSET 0x18u   /* RW */
#define DMA_ENGINE_REGS_DST_RESET 0x00000000u
#define DMA_ENGINE_REGS_LEN_OFFSET 0x1Cu   /* RW */
#define DMA_ENGINE_REGS_LEN_RESET 0x00000000u
#define DMA_ENGINE_REGS_STATUS_OFFSET 0x20u   /* CMD */
#define DMA_ENGINE_REGS_STATUS_RESET 0x00000000u
#define DMA_ENGINE_REGS_STATUS_BUSY_SHIFT 0u
#define DMA_ENGINE_REGS_STATUS_BUSY_MASK 0x00000001u
#define DMA_ENGINE_REGS_STATUS_DONE_SHIFT 8u
#define DMA_ENGINE_REGS_STATUS_DONE_MASK 0x00000100u
#define DMA_ENGINE_REGS_STATUS_ERROR_SHIFT 9u
#define DMA_ENGINE_REGS_STATUS_ERROR_MASK 0x00000200u
#endif /* DMA_ENGINE_REGS_H */
